def _diff(self, level, parents_ids=frozenset(), _original_type=None):  # noqa: C901
    """
    The main diff method

    **parameters**

    level: the tree level or tree node
    parents_ids: the ids of all the parent objects in the tree from the current node.
    _original_type: If the objects had an original type that was different than what currently exists in the level.t1
    and t2.
    """
    if self._count_diff() is StopIteration:
        return

    if self._use_custom_operator(level):
        return

    if level.t1 is level.t2:
        return

    if self._skip_this(level):
        return

    if get_type(level.t1) != get_type(level.t2):
        report_type_change = True
        if get_type(level.t2) is get_type(str):
            if str(level.t1).startswith("(") and str(level.t1).endswith(")"):
                report_type_change = False
                matched = re.match(re.compile(str(level.t1)[1:-1]), str(level.t2))
                if matched:
                    return
        for type_group in self.ignore_type_in_groups:
            if self.type_check_func(level.t1, type_group) and self.type_check_func(level.t2, type_group):
                report_type_change = False
                break
        if report_type_change:
            self._diff_types(level)
            return
        # This is an edge case where t1=None or t2=None and None is in the ignore type group.
        if level.t1 is None or level.t2 is None:
            self._report_result("values_changed", level)
            return

    if self.ignore_nan_inequality and isinstance(level.t1, float) and str(level.t1) == str(level.t2) == "nan":
        return

    if isinstance(level.t1, booleans):
        self._diff_booleans(level)

    if isinstance(level.t1, strings):
        self._diff_str(level)

    elif isinstance(level.t1, times):
        self._diff_datetimes(level)

    elif isinstance(level.t1, numbers):
        self._diff_numbers(level)

    elif isinstance(level.t1, Mapping):
        self._diff_dict(level, parents_ids)

    elif isinstance(level.t1, tuple):
        self._diff_tuple(level, parents_ids)

    elif isinstance(level.t1, (set, frozenset, OrderedSet)):
        self._diff_set(level)

    elif isinstance(level.t1, np_ndarray):
        self._diff_numpy_array(level, parents_ids)

    elif isinstance(level.t1, Iterable):
        self._diff_iterable(level, parents_ids, _original_type=_original_type)

    else:
        self._diff_obj(level, parents_ids)


def _diff_str(self, level):  # noqa: C901
    """Compare strings"""
    if self.ignore_string_case:
        level.t1 = level.t1.lower()
        level.t2 = level.t2.lower()

    if type(level.t1) == type(level.t2) and level.t1 == level.t2:  # NOQA
        return

    # do we add a diff for convenience?
    do_diff = True
    t1_str = level.t1
    t2_str = level.t2

    if isinstance(level.t1, bytes_type):
        try:
            t1_str = level.t1.decode("ascii")
        except UnicodeDecodeError:
            do_diff = False

    if isinstance(level.t2, bytes_type):
        try:
            t2_str = level.t2.decode("ascii")
        except UnicodeDecodeError:
            do_diff = False

    if t1_str == t2_str:
        return
    if t1_str != t2_str:
        if t1_str.startswith("(") and t1_str.endswith(")"):
            matched = re.match(re.compile(t1_str[1:-1]), t2_str)
            if matched:
                return
    if do_diff:
        if "\n" in t1_str or "\n" in t2_str:
            diff = difflib.unified_diff(t1_str.splitlines(), t2_str.splitlines(), lineterm="")
            diff = list(diff)
            if diff:
                level.additional["diff"] = "\n".join(diff)

    self._report_result("values_changed", level)


def rpc_error_init_ncclient(self, raw, errs=None):
    self._raw = raw
    if errs is None:
        # Single RPCError
        self._errlist = None
        for attr in six.itervalues(RPCError.tag_to_attr):
            setattr(self, attr, None)
        for subele in raw:
            attr = RPCError.tag_to_attr.get(subele.tag, None)
            if attr is not None:
                setattr(self, attr, subele.text if attr != "_info" else to_xml(subele))
            OperationError.__init__(self, json.dumps(self.to_dict(), indent=4).replace('\\"', "'"))
    else:
        # Multiple errors returned. Errors is a list of RPCError objs
        errs_to_report = []
        for err in errs:
            err_to_report = {
                "error-type": err.type,
                "error-tag": err.tag,
                "error-app-tag": err.app_tag,
                "error-severity": err.severity,
                "error-info": err.info,
                "error-path": err.path,
                "error-message": err.message,
            }
            errs_to_report.append(err_to_report)
        raise OperationError(json.dumps(errs_to_report, indent=4))


def rpc_error_init_netconf_client(self, raw, ele):
    msg = []
    types = ele.xpath("/nc:rpc-reply/nc:rpc-error/nc:error-type", namespaces=NAMESPACES)
    tags = ele.xpath("/nc:rpc-reply/nc:rpc-error/nc:error-tag", namespaces=NAMESPACES)
    app_tags = ele.xpath("/nc:rpc-reply/nc:rpc-error/nc:error-app-tag", namespaces=NAMESPACES)
    messages = ele.xpath("/nc:rpc-reply/nc:rpc-error/nc:error-message", namespaces=NAMESPACES)
    severities = ele.xpath("/nc:rpc-reply/nc:rpc-error/nc:error-severity", namespaces=NAMESPACES)
    infos = ele.xpath("/nc:rpc-reply/nc:rpc-error/nc:error-info", namespaces=NAMESPACES)
    paths = ele.xpath("/nc:rpc-reply/nc:rpc-error/nc:error-path", namespaces=NAMESPACES)
    elements = types
    for element_id, _ in enumerate(elements):
        err_type = types[element_id].text if types else None
        err_tag = tags[element_id].text if tags else None
        err_app_tag = app_tags[element_id].text if app_tags else None
        err_message = messages[element_id].text if messages else None
        err_severity = severities[element_id].text if severities else None
        err_info = infos[element_id].text if infos else None
        err_path = paths[element_id].text if paths else None
        msg.append(
            {
                "type": err_type,
                "tag": err_tag,
                "app_tag": err_app_tag,
                "severity": err_severity,
                "info": err_info,
                "path": err_path,
                "message": err_message,
            }
        )
    super(RpcError, self).__init__(json.dumps(msg, indent=4))


def modified_device_handler(device_params):
    if device_params is None:
        device_params = {}
    handler = device_params.get("handler", None)
    if handler:
        return handler(device_params)
    device_name = device_params.get("name", "default")
    class_name = "%sDeviceHandler" % device_name.capitalize()
    try:
        devices_module_name = "taf.ul.oran_mplane.core.devices.%s" % device_name
        dev_module_obj = __import__(devices_module_name)
        handler_module_obj = getattr(getattr(dev_module_obj.ul.oran_mplane.core, "devices"), device_name)
    except ModuleNotFoundError:
        devices_module_name = "devices.%s" % device_name
        dev_module_obj = __import__(devices_module_name)
        handler_module_obj = getattr(getattr(dev_module_obj, "devices"), device_name)
    class_obj = getattr(handler_module_obj, class_name)
    handler_obj = class_obj(device_params)
    return handler_obj


def modified_edit_config(
    self, config, target="running", default_operation=None, test_option=None, error_option=None, format="xml"
):
    rpc_xml = edit_config(config, target, default_operation, test_option, error_option)
    (msg, _) = self._send_rpc(rpc_xml)
    return RPCReply(msg).xml


def ncc_client_transport_notify_notification_init(self, raw):
    self._raw = raw
    self._root_ele = to_ele(raw)
    self.timestamp = datetime.now(timezone.utc)


def netconf_client_connect_tls(
    sock: socket,
    *,
    keyfile: str = None,
    certfile: str = None,
    ca_certs: str = None,
    server_hostname: str = "",
    **_
) -> Session:
    """Connect to a NETCONF server over TLS.
    :param keyfile: Path to the key file used to identify the client
    :param certfile: Path to the certificate used to identify the client
    :param ca_certs: Path to a file containing the certificate
                     authority chains for verifying the server identity
    :param sock: An already-open TCP socket; TLS will be setup on top
                 of it
    :param server_hostname: if provided that indicates whether hostname should be verified in the SSLContext. When you
     want to ensure that the server you're connecting to is the one you expect. This is the default and recommended
     behavior for secure communication.
    """
    context = ssl.SSLContext(ssl.PROTOCOL_TLSv1_2)
    context.load_cert_chain(certfile, keyfile)
    if ca_certs:
        context.load_verify_locations(cafile=ca_certs)
        context.verify_mode = ssl.CERT_REQUIRED
    else:
        context.verify_mode = ssl.CERT_NONE
    context.check_hostname = bool(server_hostname)
    ssl_sock = context.wrap_socket(sock, server_hostname=server_hostname)
    return Session(ssl_sock)


class RpcReplyWithTimestamp(ncclient.operations.rpc.RPCReply):
    def __init__(self, raw, huge_tree=False, parsing_error_transform=None):
        super(RpcReplyWithTimestamp, self).__init__(raw, huge_tree=huge_tree,
                                                   parsing_error_transform=parsing_error_transform)
        self.timestamp = datetime.now().astimezone()


